/// The boxed call `symbol` with exactly `arity` operands.
pub fn runtime_boxed_abi(symbol: &str, arity: usize) -> Option<RuntimeBoxedAbi> {
    let abi = RuntimeFn::from_symbol(symbol)?.boxed_abi()?;
    (abi.arity() == arity).then_some(abi)
}

/// The raw direct call `symbol` with exactly `arity` operands.
pub fn runtime_raw_abi(symbol: &str, arity: usize) -> Option<RuntimeFn> {
    let function = RuntimeFn::from_symbol(symbol)?;
    (function.form() == RuntimeCallForm::RawCall && function.params() == arity).then_some(function)
}

/// Explicitly admitted positional op calls; every target consumes this mapping.
pub const RUNTIME_BOXED_OP_KINDS: &[crate::OpKind] = &[
    crate::OpKind::BytearrayCount,
    crate::OpKind::BytearrayCountSlice,
    crate::OpKind::BytearrayEndswith,
    crate::OpKind::BytearrayEndswithSlice,
    crate::OpKind::BytearrayFind,
    crate::OpKind::BytearrayFindSlice,
    crate::OpKind::BytearrayStartswith,
    crate::OpKind::BytearrayStartswithSlice,
    crate::OpKind::BytesCount,
    crate::OpKind::BytesCountSlice,
    crate::OpKind::BytesEndswith,
    crate::OpKind::BytesEndswithSlice,
    crate::OpKind::BytesFind,
    crate::OpKind::BytesFindSlice,
    crate::OpKind::BytesStartswith,
    crate::OpKind::BytesStartswithSlice,
    crate::OpKind::StringCount,
    crate::OpKind::StringCountSlice,
    crate::OpKind::StringEndswith,
    crate::OpKind::StringEndswithSlice,
    crate::OpKind::StringFind,
    crate::OpKind::StringFindSlice,
    crate::OpKind::StringStartswith,
    crate::OpKind::StringStartswithSlice,
];

pub const fn runtime_boxed_op_abi(kind: crate::OpKind) -> Option<RuntimeBoxedAbi> {
    match kind {
        crate::OpKind::BytearrayCount => RuntimeFn::BytearrayCount.boxed_abi(),
        crate::OpKind::BytearrayCountSlice => RuntimeFn::BytearrayCountSlice.boxed_abi(),
        crate::OpKind::BytearrayEndswith => RuntimeFn::BytearrayEndswith.boxed_abi(),
        crate::OpKind::BytearrayEndswithSlice => RuntimeFn::BytearrayEndswithSlice.boxed_abi(),
        crate::OpKind::BytearrayFind => RuntimeFn::BytearrayFind.boxed_abi(),
        crate::OpKind::BytearrayFindSlice => RuntimeFn::BytearrayFindSlice.boxed_abi(),
        crate::OpKind::BytearrayStartswith => RuntimeFn::BytearrayStartswith.boxed_abi(),
        crate::OpKind::BytearrayStartswithSlice => RuntimeFn::BytearrayStartswithSlice.boxed_abi(),
        crate::OpKind::BytesCount => RuntimeFn::BytesCount.boxed_abi(),
        crate::OpKind::BytesCountSlice => RuntimeFn::BytesCountSlice.boxed_abi(),
        crate::OpKind::BytesEndswith => RuntimeFn::BytesEndswith.boxed_abi(),
        crate::OpKind::BytesEndswithSlice => RuntimeFn::BytesEndswithSlice.boxed_abi(),
        crate::OpKind::BytesFind => RuntimeFn::BytesFind.boxed_abi(),
        crate::OpKind::BytesFindSlice => RuntimeFn::BytesFindSlice.boxed_abi(),
        crate::OpKind::BytesStartswith => RuntimeFn::BytesStartswith.boxed_abi(),
        crate::OpKind::BytesStartswithSlice => RuntimeFn::BytesStartswithSlice.boxed_abi(),
        crate::OpKind::StringCount => RuntimeFn::StringCount.boxed_abi(),
        crate::OpKind::StringCountSlice => RuntimeFn::StringCountSlice.boxed_abi(),
        crate::OpKind::StringEndswith => RuntimeFn::StringEndswith.boxed_abi(),
        crate::OpKind::StringEndswithSlice => RuntimeFn::StringEndswithSlice.boxed_abi(),
        crate::OpKind::StringFind => RuntimeFn::StringFind.boxed_abi(),
        crate::OpKind::StringFindSlice => RuntimeFn::StringFindSlice.boxed_abi(),
        crate::OpKind::StringStartswith => RuntimeFn::StringStartswith.boxed_abi(),
        crate::OpKind::StringStartswithSlice => RuntimeFn::StringStartswithSlice.boxed_abi(),
        _ => None,
    }
}
